v_cas:=private.weekly_source_bulk_source_cas_v1(v_cycle.id,array[v_contract.client_id]);
if v_cas is distinct from source_admission->'source_cas' then
  raise exception 'AGENCY_CHANGE_SOURCE_FOOTPRINT_CHANGED_UNDER_LOCK' using errcode='40001';end if;

dependency_tokens:=capture->'source_dependency_tokens';
if jsonb_typeof(dependency_tokens) is distinct from 'array'
 or capture->>'source_dependency_tokens_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
  'WEEKLY_SOURCE_AGENCY_SOURCE_DEPENDENCY_TOKENS_V1',dependency_tokens),'hex') then
 raise exception 'AGENCY_CHANGE_NATIVE_SOURCE_FOOTPRINT_REQUIRED' using errcode='55000';end if;
-- Keep the actual full immutable tokens on the same request, and only their
-- native digest in the original small capture / request-input hash.
capture:=capture-'source_dependency_tokens';
if capture->>'initial_row_signature' is distinct from p_expected_signature then

if v_original->>'source_dependency_tokens_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
  'WEEKLY_SOURCE_AGENCY_SOURCE_DEPENDENCY_TOKENS_V1',v_request.source_dependency_tokens),'hex') then
  raise exception 'AGENCY_CHANGE_ORIGINAL_NATIVE_SOURCE_FOOTPRINT_CHANGED' using errcode='55000';end if;
source_admission:=private.weekly_source_agency_source_phase_admit_v1(v_ts.timesheet_id,p_actor_user_id,
  v_request.candidate_id,v_request.source_cycle_id,v_request.client_id,v_request.source_cas,native_admission);
select coalesce(jsonb_agg(value order by value),'[]'::jsonb) into merged_tokens from(
  select distinct value from jsonb_array_elements(v_request.current_source_dependency_tokens||(source_admission->'source_dependency_tokens'))
) native_current_union;
if merged_tokens is distinct from v_request.current_source_dependency_tokens then
  source_admission:=(source_admission-'source_dependency_tokens')||jsonb_build_object('request_id',v_request.id,
    'request_sha256',encode(v_request.request_sha256,'hex'),'source_dependency_tokens_sha256',encode(
      private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_AGENCY_SOURCE_DEPENDENCY_TOKENS_V1',merged_tokens),'hex'));
  update private.weekly_source_agency_timesheet_change_requests set current_source_dependency_tokens=merged_tokens,
    native_receipts=native_receipts||jsonb_build_object('source_admission',source_admission),
    updated_by_user_id=p_actor_user_id,updated_at_utc=transaction_timestamp(),version=version+1
    where id=v_request.id returning * into v_request;
  insert into public.audit_events(id,ts_utc,actor_user_id,actor_role_at_time,object_type,object_id_text,action,after_json,reason,correlation_id)
    select gen_random_uuid(),transaction_timestamp(),p_actor_user_id,a.role,'WEEKLY_SOURCE_AGENCY_CHANGE',v_request.id::text,
      'NATIVE_SOURCE_FOOTPRINT_RETAINED',jsonb_build_object('phase',v_request.phase,'request_version',v_request.version,
        'original_creator_user_id',v_request.actor_user_id,'current_resumer_user_id',p_actor_user_id,
        'source_dependency_tokens_sha256',source_admission->>'source_dependency_tokens_sha256'),v_request.reason,v_request.request_key
    from public.tms_users a where a.id=p_actor_user_id and a.is_active;
  if not found then raise exception 'AGENCY_CHANGE_CURRENT_ACTOR_UNAVAILABLE' using errcode='42501';end if;
end if;
v_signature:=public.timesheet_lifecycle_guard_signature_v1(v_ts.timesheet_id,v_week.id,false);
